import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"Meter","description":"","frontmatter":{},"headers":[],"relativePath":"components/meter.md","filePath":"components/meter.md"}'),d={name:"components/meter.md"};function i(s,e,h,n,c,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="meter" tabindex="-1">Meter <a class="header-anchor" href="#meter" aria-label="Permalink to &quot;Meter&quot;">​</a></h1><p>Meter shows how much of a limit is used, such as storage.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it with a name and the amount as text. Near the limit set <code>tone</code> to <code>warn</code>, and over it to <code>over</code>; where &quot;near&quot; begins is the application&#39;s choice. The progress of a task is a <a href="./progress">Progress</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td>required</td><td>The amount used</td></tr><tr><td><code>max</code></td><td>required</td><td>The limit</td></tr><tr><td><code>tone</code></td><td></td><td><code>warn</code> near the limit, <code>over</code> past it</td></tr><tr><td><code>label</code></td><td></td><td>The name, at the left above the bar</td></tr><tr><td><code>text</code></td><td></td><td>The amount as text, at the right above the bar</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The name and the amount are body text, not trimmed, gap-xs above a bar gap-sm high. The bar is the line color and fills with the solid color from the left, up to the share used (from 0 to 100%). <code>warn</code> turns the fill and the amount yellow, <code>over</code> red. The bar is a <code>meter</code> for assistive technology, named by <code>label</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/meter/" title="Meter" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/meter/" target="_blank" rel="noopener">Meter</a></figcaption></figure>',10)])])}const u=t(d,[["render",i]]);export{p as __pageData,u as default};
